<?php
declare(strict_types=1);
namespace App\Services;
final class SmtpMailer {
 private $socket;
 public function send(array $smtp,string $to,string $subject,string $html,string $text,string $from,string $replyTo=''):void { $host=$smtp['smtp_host'];$ssl=$smtp['smtp_security']==='ssl';$this->socket=@stream_socket_client(($ssl?'ssl://':'').$host.':'.$smtp['smtp_port'],$errno,$err,20);if(!$this->socket)throw new \RuntimeException("SMTP: $err");stream_set_timeout($this->socket,20);$this->expect(220);$this->cmd('EHLO localhost',250);if($smtp['smtp_security']==='tls'){$this->cmd('STARTTLS',220);if(!stream_socket_enable_crypto($this->socket,true,STREAM_CRYPTO_METHOD_TLS_CLIENT))throw new \RuntimeException('TLS indisponível');$this->cmd('EHLO localhost',250);}$this->cmd('AUTH LOGIN',334);$this->cmd(base64_encode($smtp['smtp_username']),334);$this->cmd(base64_encode($smtp['password']),235);$this->cmd('MAIL FROM:<'.$from.'>',250);$this->cmd('RCPT TO:<'.$to.'>',250);$this->cmd('DATA',354);$b='b'.bin2hex(random_bytes(8));$headers="From: {$from}\r\nTo: {$to}\r\nSubject: =?UTF-8?B?".base64_encode($subject)."?=\r\nMIME-Version: 1.0\r\n".($replyTo?"Reply-To: {$replyTo}\r\n":'')."Content-Type: multipart/alternative; boundary=\"$b\"\r\n\r\n--$b\r\nContent-Type: text/plain; charset=UTF-8\r\n\r\n$text\r\n--$b\r\nContent-Type: text/html; charset=UTF-8\r\n\r\n$html\r\n--$b--";$this->cmd($headers."\r\n.",250);$this->cmd('QUIT',221);fclose($this->socket); }
 private function cmd(string $line,int $expected):void{fwrite($this->socket,$line."\r\n");$this->expect($expected);}private function expect(int $code):void{$r='';do{$l=fgets($this->socket,1024);if($l===false)throw new \RuntimeException('SMTP desconectado');$r.=$l;}while(isset($l[3])&&$l[3]==='-');if((int)substr($r,0,3)!==$code)throw new \RuntimeException('SMTP: '.trim($r));}
}
